import{_ as e,o as a,c as r,ag as o}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Capstone Ideas","description":"","frontmatter":{"source":"projects/capstone-ideas.md"},"headers":[],"relativePath":"projects/capstone-ideas.md","filePath":"projects/capstone-ideas.md"}'),s={name:"projects/capstone-ideas.md"};function d(n,t,i,h,l,c){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="capstone-ideas" tabindex="-1">Capstone Ideas <a class="header-anchor" href="#capstone-ideas" aria-label="Permalink to &quot;Capstone Ideas&quot;">​</a></h1><blockquote><p>Twenty-five ideas sized for the capstone&#39;s six weeks (11–16), a list of ideas that are too big, and a method for shrinking your own idea until it fits.</p></blockquote><p>The best capstone is a small app you care about, finished and secure, with one or two things done really well. Use these ideas as they are, remix them, or use them to size-check your own. Every idea must follow the <a href="./#the-three-project-rules">three project rules</a>.</p><p><strong>Feature types</strong> (you need at least two; pairs at least three, or two plus a scope increase approved at the pitch; details in <a href="./capstone.html#feature-types-include-at-least-two">Capstone (weeks 11–16): Feature types: include at least two</a>), and the tested <strong>starter pattern</strong> for each, which you copy and adapt (<a href="https://github.com/Boyu-Zhang-UOI/vc101-capstone-starter/blob/main/README.md#feature-patterns" target="_blank" rel="noreferrer">feature patterns</a>):</p><table tabindex="0"><thead><tr><th></th><th>Feature type</th><th>Starter pattern</th><th>Short name in the tables below</th></tr></thead><tbody><tr><td><strong>(a)</strong></td><td>Server-side API call with a hidden key, for example an LLM feature</td><td><code>api/ask.js</code> with <code>lib/llm.js</code></td><td><strong>AI route</strong></td></tr><tr><td><strong>(b)</strong></td><td>Database with access rules (row-level security) and/or sign-in</td><td><code>public/config.js</code>, <code>public/lib/db.js</code> and <code>supabase/policies.sql</code></td><td><strong>db + RLS</strong></td></tr><tr><td><strong>(c)</strong></td><td>Data visualization</td><td><code>public/lib/chart.js</code> (an SVG bar chart, with a tested data-prep function)</td><td><strong>chart</strong></td></tr><tr><td><strong>(d)</strong></td><td>External public API</td><td><code>api/weather.js</code> (a public API with no key, tested with a fake response)</td><td><strong>public API</strong></td></tr></tbody></table><p><strong>Sign-in</strong> (user accounts) has no starter pattern. Add it only if your access rules need it, and plan extra time; ideas that need it are marked &quot;+ sign-in&quot;. A pattern marked &quot;adapted&quot; needs more than small changes.</p><p>Each idea lists the feature types and starter patterns it would naturally use, and a <strong>scope warning</strong>: the part most likely to eat your six weeks.</p><h2 id="learning-and-study" tabindex="-1">Learning and study <a class="header-anchor" href="#learning-and-study" aria-label="Permalink to &quot;Learning and study&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Idea</th><th>What it does</th><th>Features (starter patterns)</th><th>Scope warning</th></tr></thead><tbody><tr><td><strong>Quiz-me study buddy</strong></td><td>Paste your notes; an LLM writes five multiple-choice questions; your scores are saved and charted over time</td><td>a (AI route), b (db + RLS), c (chart)</td><td>Grading free-text answers with an LLM is unreliable. Stick to multiple choice</td></tr><tr><td><strong>Flashcards with spaced review</strong></td><td>Decks of cards; cards you miss come back sooner; a chart of cards learned per week</td><td>b (db + RLS), c (chart)</td><td>Keep the scheduling rule simple (three boxes: new, learning, known)</td></tr><tr><td><strong>Vocabulary builder</strong></td><td>Save words you meet; an LLM writes example sentences; review mode</td><td>a (AI route), b (db + RLS)</td><td>The model can be wrong about meanings and translations. Label its output as AI-generated</td></tr><tr><td><strong>Plain-English error explainer</strong></td><td>Paste an error message; get an explanation and where to look; keep a history of errors you&#39;ve solved</td><td>a (AI route), b (db + RLS)</td><td>Warn users never to paste keys. Strip anything that looks like a key on the server before calling the model</td></tr><tr><td><strong>Pomodoro study stats</strong></td><td>Focus timer, sessions saved by subject, weekly chart</td><td>b (db + RLS), c (chart)</td><td>Timers in background tabs are unreliable. Save start and end times, not ticks</td></tr></tbody></table><h2 id="personal-life-and-habits" tabindex="-1">Personal life and habits <a class="header-anchor" href="#personal-life-and-habits" aria-label="Permalink to &quot;Personal life and habits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Idea</th><th>What it does</th><th>Features (starter patterns)</th><th>Scope warning</th></tr></thead><tbody><tr><td><strong>Habit tracker with a streak heatmap</strong></td><td>Tick habits daily; a calendar heatmap shows streaks</td><td>b (db + RLS), c (chart, adapted from bars to a grid)</td><td>Dates and time zones are harder than they look. Define &quot;a day&quot; in your spec</td></tr><tr><td><strong>Workout log with personal bests</strong></td><td>Log exercises and sets; chart progress per exercise</td><td>b (db + RLS), c (chart)</td><td>Don&#39;t add a big exercise catalog. Let users type their own exercise names</td></tr><tr><td><strong>Mood and energy journal</strong></td><td>Short daily entries; weekly chart; optional LLM summary of the week</td><td>b (db + RLS), c (chart), a (AI route)</td><td>Sensitive data. Demo only with made-up entries, and don&#39;t send real journal text to a free AI tier</td></tr><tr><td><strong>Application tracker</strong></td><td>Track job or internship applications through stages; a chart of your pipeline</td><td>b (db + RLS), c (chart)</td><td>Personal data. Use invented companies and contacts in the demo</td></tr><tr><td><strong>Decision helper</strong></td><td>List options, weight your criteria, see a chart of scores; an LLM plays devil&#39;s advocate</td><td>c (chart), a (AI route)</td><td>The weighting math is easy; the interface for editing weights isn&#39;t. Sketch it first</td></tr></tbody></table><h2 id="food-and-home" tabindex="-1">Food and home <a class="header-anchor" href="#food-and-home" aria-label="Permalink to &quot;Food and home&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Idea</th><th>What it does</th><th>Features (starter patterns)</th><th>Scope warning</th></tr></thead><tbody><tr><td><strong>Fridge-to-dinner</strong></td><td>Keep a pantry list; an LLM suggests recipes from what you have; save favorites</td><td>a (AI route), b (db + RLS)</td><td>AI suggestions are not allergy or safety advice. Say so on the page</td></tr><tr><td><strong>Meal planner with a shopping list</strong></td><td>Plan the week&#39;s meals; generate a combined shopping list; chart meals by category</td><td>b (db + RLS), c (chart)</td><td>Nutrition data is messy. Skip calories, or use a small made-up table</td></tr><tr><td><strong>Plant care log</strong></td><td>Log waterings; local weather adjusts the &quot;water soon&quot; hint; watering history chart</td><td>d (public API), b (db + RLS), c (chart)</td><td>Ask for a city, never a home address. Cache weather results so you don&#39;t hit rate limits</td></tr><tr><td><strong>Household chore rota</strong></td><td>Chores rotate among housemates (nicknames); a fairness chart shows who did what</td><td>b (db + RLS), c (chart)</td><td>Sharing data between several accounts makes the access rules much harder. Start with one account that manages the whole house</td></tr></tbody></table><h2 id="hobbies-and-fun-single-player" tabindex="-1">Hobbies and fun (single-player) <a class="header-anchor" href="#hobbies-and-fun-single-player" aria-label="Permalink to &quot;Hobbies and fun (single-player)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Idea</th><th>What it does</th><th>Features (starter patterns)</th><th>Scope warning</th></tr></thead><tbody><tr><td><strong>Reading tracker with book search</strong></td><td>Search a public book API to add books; track pages; chart pages per month</td><td>d (public API, adapted to a book API), b (db + RLS), c (chart)</td><td>Search results are messy (many editions). Show the top five and let the user pick</td></tr><tr><td><strong>Board-game night stats</strong></td><td>Record games and scores for a regular group (nicknames); win-rate charts</td><td>b (db + RLS), c (chart)</td><td>This is score-keeping, not a multiplayer game. Keep it that way</td></tr><tr><td><strong>Music practice log</strong></td><td>Log practice sessions; an LLM suggests tomorrow&#39;s practice plan; weekly totals chart</td><td>b (db + RLS), a (AI route), c (chart)</td><td>Keep the LLM&#39;s job narrow (one plan, a fixed format)</td></tr><tr><td><strong>Story-prompt generator</strong></td><td>Pick a genre and mood; an LLM writes a prompt; save your drafts</td><td>a (AI route), b (db + RLS)</td><td>Long outputs use more of your quota. Set a maximum length on both input and output</td></tr></tbody></table><h2 id="data-and-the-world" tabindex="-1">Data and the world <a class="header-anchor" href="#data-and-the-world" aria-label="Permalink to &quot;Data and the world&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Idea</th><th>What it does</th><th>Features (starter patterns)</th><th>Scope warning</th></tr></thead><tbody><tr><td><strong>City weather and air dashboard</strong></td><td>Pick a city; charts of the week&#39;s forecast and air quality</td><td>d (public API), c (chart)</td><td>Pick one or two data series. Every extra chart is extra testing</td></tr><tr><td><strong>Public data explorer</strong></td><td>Choose one open dataset (your city&#39;s bikes, trees or library loans) and chart it with filters</td><td>d (public API, adapted to your dataset), c (chart)</td><td>Cleaning the data can take all your time. Choose a dataset that&#39;s already tidy, and a small slice of it</td></tr><tr><td><strong>Trip budget planner</strong></td><td>Plan a trip budget by category; convert currencies with a public rates API; spending chart</td><td>d (public API), c (chart), b (db + RLS)</td><td>No real payments and no bank connections. Users type amounts by hand</td></tr><tr><td><strong>Countdown board with public holidays</strong></td><td>Your events plus public holidays from an API; days-until view</td><td>d (public API), b (db + RLS)</td><td>Holiday APIs differ by country. Support one country well</td></tr></tbody></table><h2 id="clubs-and-groups-with-made-up-members" tabindex="-1">Clubs and groups (with made-up members) <a class="header-anchor" href="#clubs-and-groups-with-made-up-members" aria-label="Permalink to &quot;Clubs and groups (with made-up members)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Idea</th><th>What it does</th><th>Features (starter patterns)</th><th>Scope warning</th></tr></thead><tbody><tr><td><strong>Club event sign-up board</strong></td><td>An organizer posts events; members sign up; only the organizer can edit or delete; a chart of turnout</td><td>b (db + RLS, + sign-in), c (chart)</td><td>Public sign-up forms attract spam. Demo with test accounts only, no real names</td></tr><tr><td><strong>Office-hours queue</strong></td><td>Students join a queue; a helper marks them done; stats on wait times</td><td>b (db + RLS, + sign-in for the helper), c (chart)</td><td>Live updates are hard. A &quot;Refresh&quot; button is fine for a capstone</td></tr><tr><td><strong>Class Q&amp;A with AI first drafts</strong></td><td>Post a question; an LLM drafts an answer the organizer approves before anyone sees it</td><td>a (AI route), b (db + RLS, + sign-in)</td><td>Two roles (asker, organizer) need careful access rules. Write them in <code>SPEC.md</code> before you build</td></tr></tbody></table><h2 id="too-big-for-the-capstone" tabindex="-1">Too big for the capstone <a class="header-anchor" href="#too-big-for-the-capstone" aria-label="Permalink to &quot;Too big for the capstone&quot;">​</a></h2><p>These fail in a six-week, free-tier capstone, however good the agent is. Each has a smaller version that works.</p><table tabindex="0"><thead><tr><th>Too big</th><th>Why</th><th>Try instead</th></tr></thead><tbody><tr><td><strong>A social network</strong></td><td>Profiles, feeds, following, moderation and privacy rules for many users. Moltbook, a vibe-coded social network, exposed about 35,000 emails through missing access rules (<a href="https://www.wiz.io/blog/exposed-moltbook-database-reveals-millions-of-api-keys" target="_blank" rel="noreferrer">Wiz</a>)</td><td>A single-purpose board for one group, with made-up members and one clear access rule</td></tr><tr><td><strong>A marketplace</strong></td><td>Two kinds of users, listings, messaging, trust and payments</td><td>A &quot;wish list&quot; you share read-only with a link</td></tr><tr><td><strong>Anything with real payments</strong></td><td>Against free hosting terms, and high-stakes code</td><td>A fake &quot;checkout&quot; button that shows a thank-you message</td></tr><tr><td><strong>Anything with real personal data</strong></td><td>Health records, other people&#39;s contact details, student records: legal and ethical risk</td><td>The same app with made-up data, and a README note on what real use would require</td></tr><tr><td><strong>Multiplayer real-time games</strong></td><td>Real-time sync, cheating, lag and hosting are each a project in themselves</td><td>A single-player game with a saved leaderboard (b + c)</td></tr><tr><td><strong>An AI agent that acts for you</strong> (reads your email, posts for you)</td><td>Private data, untrusted content and a way to send data out: the &quot;lethal trifecta&quot; (<a href="https://simonwillison.net/2025/Jun/16/the-lethal-trifecta/" target="_blank" rel="noreferrer">Willison</a>)</td><td>An LLM that drafts, and you copy the draft yourself</td></tr><tr><td><strong>A native phone app</strong></td><td>App stores, device builds and review processes</td><td>A web app that works well on a phone screen</td></tr><tr><td><strong>&quot;Like Spotify / Uber / Airbnb, but for X&quot;</strong></td><td>Each is years of work by large teams</td><td>The one screen of it you&#39;d use most</td></tr></tbody></table><h2 id="how-to-shrink-an-idea" tabindex="-1">How to shrink an idea <a class="header-anchor" href="#how-to-shrink-an-idea" aria-label="Permalink to &quot;How to shrink an idea&quot;">​</a></h2><p>Work through these steps until your idea fits on one page of <code>SPEC.md</code> and six weeks of evenings.</p><ol><li><strong>One user, one main screen, one core loop.</strong> Write the loop as a sentence: &quot;I add a thing, the app does something with it, I see the result.&quot;</li><li><strong>Replace &quot;everyone&quot; with &quot;me&quot;.</strong> If the idea needs strangers to use it, make a version that&#39;s useful to you alone first.</li><li><strong>Replace real-time with refresh.</strong> A &quot;Refresh&quot; button beats live updates.</li><li><strong>Replace accounts with one account, or none.</strong> Add sign-in only if your access rules need it, and then only email sign-in with test users.</li><li><strong>Replace real data with made-up data.</strong> Make a small, realistic fake dataset early; you&#39;ll need it for tests and your demo anyway.</li><li><strong>Keep only the MUSTs.</strong> Move every SHOULD and COULD to &quot;Out of scope&quot;. You can add them back in week 15 if you have time.</li><li><strong>Pick exactly two feature types</strong> (pairs: three, or two plus an approved scope increase), ideally ones with a starter pattern. Extra ones rarely get the testing and security work they need.</li><li><strong>Run the week 12 test.</strong> <a href="./capstone.html#milestones">Milestone 1</a> asks for two working features at a production URL by the end of week 12. Could you get the core loop working, roughly, by then? If not, cut again.</li></ol><p><strong>A worked example.</strong> Idea: &quot;Instagram for plant lovers&quot;.</p><ul><li>Step 2: forget strangers; it&#39;s for me and my plants.</li><li>Step 4: no followers, no profiles. One account.</li><li>Step 5: photos mean file storage and privacy questions; drop them.</li><li>Step 7: pick (b) a database with row-level security for my plants and waterings (db + RLS), and (d) a weather API for a &quot;water soon&quot; hint (public API, close to the starter&#39;s <code>api/weather.js</code>). Add (c) a watering-history chart only if week 13 goes well.</li><li>Result: <strong>&quot;Plant care log&quot;</strong>, from the list above. Still yours, and it can be finished.</li></ul><h2 id="before-you-pitch-a-checklist" tabindex="-1">Before you pitch: a checklist <a class="header-anchor" href="#before-you-pitch-a-checklist" aria-label="Permalink to &quot;Before you pitch: a checklist&quot;">​</a></h2><ul><li>☐ I can describe the problem and the user in two sentences.</li><li>☐ I picked at least two feature types (pairs: three, or two plus a scope increase I&#39;m asking for), and I know what each one does in my app.</li><li>☐ I know which starter patterns I&#39;ll adapt, and whether I need anything the starter doesn&#39;t have (such as sign-in).</li><li>☐ If I use a public API: I checked its terms, whether it needs a key, and its rate limits.</li><li>☐ My idea breaks none of the <a href="./#the-three-project-rules">three project rules</a>.</li><li>☐ It isn&#39;t on the &quot;too big&quot; list, or I&#39;ve shrunk it.</li><li>☐ I&#39;ve written down at least three things that are out of scope.</li><li>☐ I know my biggest risk and have a plan B.</li></ul><p>Then write your <a href="./capstone.html#the-pitch">pitch</a>. It&#39;s due 72 hours before week 11 Studio A.</p>',30)])])}const g=e(s,[["render",d]]);export{p as __pageData,g as default};
